<?php
require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';
$role=$_SESSION['kode_role'];if(!in_array($role,['ADMIN','OPERATOR_PRODI'],true)){http_response_code(403);die('403 - Akses ditolak.');}
$prodis=[]; $res=mysqli_query($koneksi,"SELECT ps.id_program_studi,ps.kode_program_studi,ps.nama_program_studi,f.nama_fakultas FROM program_studi ps JOIN fakultas f ON ps.id_fakultas=f.id_fakultas WHERE ps.status_aktif='Aktif' ORDER BY f.nama_fakultas,ps.nama_program_studi");while($r=mysqli_fetch_assoc($res))$prodis[]=$r;
$error='';$data=['npm'=>'','nama_mahasiswa'=>'','jenis_kelamin'=>'L','tempat_lahir'=>'','tanggal_lahir'=>'','tanggal_masuk'=>date('Y-m-d'),'alamat'=>'','status_mahasiswa'=>'Aktif','id_program_studi'=>$role==='OPERATOR_PRODI'?($_SESSION['id_program_studi']??''): ''];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();foreach($data as $k=>$v)$data[$k]=trim($_POST[$k]??$v);if($data['npm']===''||$data['nama_mahasiswa']===''||$data['id_program_studi']===''||$data['tanggal_masuk']==='')$error='NPM, nama, prodi, dan tanggal masuk wajib diisi.';if($role==='OPERATOR_PRODI' && (int)$data['id_program_studi']!==(int)$_SESSION['id_program_studi'])$error='Anda hanya dapat menambah mahasiswa pada Program Studi sendiri.';
if(!$error){$stmt=mysqli_prepare($koneksi,"INSERT INTO mahasiswa(id_program_studi,npm,nama_mahasiswa,jenis_kelamin,tempat_lahir,tanggal_lahir,tanggal_masuk,alamat,status_mahasiswa) VALUES(?,?,?,?,?,?,?,?,?)");mysqli_stmt_bind_param($stmt,'issssssss',$data['id_program_studi'],$data['npm'],$data['nama_mahasiswa'],$data['jenis_kelamin'],$data['tempat_lahir'],$data['tanggal_lahir'],$data['tanggal_masuk'],$data['alamat'],$data['status_mahasiswa']);if(mysqli_stmt_execute($stmt)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'mahasiswa',(string)mysqli_insert_id($koneksi),'INSERT',null,$data);flash('success','Data mahasiswa berhasil ditambahkan.');redirect_to('mahasiswa.php');}$error='Gagal menyimpan: '.mysqli_stmt_error($stmt);mysqli_stmt_close($stmt);}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tambah Mahasiswa</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading"><span class="eyebrow">DATA AKADEMIK</span><h1>Tambah Mahasiswa</h1><p>Isi data mahasiswa dengan lengkap.</p></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="dashboard-panel form-panel"><form method="post"><div class="form-grid"><div class="form-group"><label>NPM *</label><input name="npm" required value="<?=e($data['npm'])?>"></div><div class="form-group"><label>Nama Mahasiswa *</label><input name="nama_mahasiswa" required value="<?=e($data['nama_mahasiswa'])?>"></div><div class="form-group"><label>Program Studi *</label><select name="id_program_studi" required <?php if($role==='OPERATOR_PRODI')echo'disabled';?>><?php foreach($prodis as $p):?><option value="<?=$p['id_program_studi']?>" <?=$data['id_program_studi']==$p['id_program_studi']?'selected':''?>><?=e($p['nama_fakultas'].' - '.$p['nama_program_studi'])?></option><?php endforeach;?></select><?php if($role==='OPERATOR_PRODI'):?><input type="hidden" name="id_program_studi" value="<?=e($data['id_program_studi'])?>"><?php endif;?></div><div class="form-group"><label>Jenis Kelamin *</label><select name="jenis_kelamin"><option value="L" <?=$data['jenis_kelamin']==='L'?'selected':''?>>Laki-laki</option><option value="P" <?=$data['jenis_kelamin']==='P'?'selected':''?>>Perempuan</option></select></div><div class="form-group"><label>Tempat Lahir</label><input name="tempat_lahir" value="<?=e($data['tempat_lahir'])?>"></div><div class="form-group"><label>Tanggal Lahir</label><input type="date" name="tanggal_lahir" value="<?=e($data['tanggal_lahir'])?>"></div><div class="form-group"><label>Tanggal Masuk *</label><input type="date" name="tanggal_masuk" required value="<?=e($data['tanggal_masuk'])?>"></div><div class="form-group"><label>Status</label><select name="status_mahasiswa"><?php foreach(['Aktif','Cuti','Lulus','Mengundurkan Diri','Drop Out','Tidak Aktif'] as $s):?><option <?=$data['status_mahasiswa']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div></div><div class="form-group"><label>Alamat</label><textarea name="alamat" rows="4"><?=e($data['alamat'])?></textarea></div><div class="form-actions"><a class="btn btn-outline" href="mahasiswa.php">Batal</a><button class="btn btn-primary">Simpan</button></div></form></div></main><script src="script.js"></script></body></html>